```ts
interface LightState {
  next(light: TrafficLight): void;
  color(): string;
}

class RedState implements LightState {
  next(light) { light.setState(new GreenState()); }
  color() { return 'red'; }
}
class GreenState implements LightState {
  next(light) { light.setState(new YellowState()); }
  color() { return 'green'; }
}
class YellowState implements LightState {
  next(light) { light.setState(new RedState()); }
  color() { return 'yellow'; }
}

class TrafficLight {
  private state: LightState = new RedState();
  setState(s: LightState) { this.state = s; }
  advance() { this.state.next(this); }
  color() { return this.state.color(); }
}

const light = new TrafficLight();
light.advance();      // red -> green, no switch statement anywhere
```

Compare this to an enum + switch version: `advance()` there would need a `switch (this.status) { case 'red': ...; case 'green': ...; }` that grows every time a state is added. Here, each state only knows its own single transition.
